insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('sam-pathways-five-asks-2026-11-16','fact','Sam''s five CPL Pathways asks (2026-11-16)','Sam, in session, 2026-11-16, verbatim: "1. Add Request Adopt links to course cards on programs wherever possible 2. Add Sierra bubble on bottom right and have it open to sidebar instead of new tab 3. Add link on course cards to SLOs and Objectives if they are collected and have them open to a side bar 4. Use full width of window for everything on this tab 5. ... add a timer that shows progress"',array['cpl-pathways','my-college-action-page','sam'],'verified','Sam in session S667, 2026-11-16; carried out in #3402','Sam Lee',now(),'SkyPlover (S667)',date '2026-11-16'),
('d-pathways-five-built-s667','decision','CPL Pathways: how the five asks were built (#3402)','S667, #3402 (da29bf82): Request Adopt is the map_links.js line per Could adopt or For consideration credential, in both viewers; Sierra''s chip shows on tabs named in window.CPL_SIERRA_TABS (library.js reads it too); SLOs and objectives open a non-modal right panel reading course_outcomes kind=in.(slo,objective); the CPL Visual streams its 5 files into a byte-driven bar and a clock.',array['cpl-pathways','my-college-action-page','decision'],'proposed','S667; #3402 and the my-college-action-page lane',null,null,'SkyPlover (S667)',date '2026-11-16'),
('d-six-cases-settled-s667','decision','The six re-clustering cases are settled; nothing waits to apply','S667, checked against #3245 and #3274: case 2 (FIRE M1274 into FIRE 130 X) and case 6 (the BUSI M1228 split) are applied; cases 1 (AJ 160), 3 (REAL) and 5 (MUS 130) stay by Sam''s Sheet 195 card 2; case 4 (MATH M1044) stays by Sam in session (d-math-m1044-stays-no-one-asked-s652). COBIx''s Nov 16 ask to apply all six yields to his rulings (#3395, #3403).',array['commons','reclustering','decision'],'proposed','S667; #3403 and the commons lane',null,null,'SkyPlover (S667)',date '2026-11-16'),
('d-rcc-two-left-no-pdf-route-s667','decision','Riverside City 30578 and 33829 stay as filed; no PDF-catalog route','S667: the plain originals of Riverside City 30578 and 33829 sit only in rcc.edu''s 2023-2024 or older PDF catalogs (d-rcc-originals-predate-curriqunet-s666). A PDF-catalog reader is not built for two records; both current records stay. Reopen on new source evidence. Next in that item: the other colleges'' plain and 2.0 pairs on curriQunet.',array['program-requirements-harvest','riverside-city','decision'],'proposed','S667; the program-requirements-harvest lane NEXT (3)',null,null,'SkyPlover (S667)',date '2026-11-16'),
('d-named-course-minimum-one-s667','decision','Slice B: the named-course minimum is one course, at extraction','S667, COBIx''s empty-heading rule (#3299): a found page is extracted only if it names at least one course; it stays found either way. Of 19,137 filed records, 9 name one course, each a real single-course certificate (Victor Valley CJ 80, EMS 60; American River FIRE 1500), so a minimum of two would refuse real programs.',array['program-requirements-harvest','slice-b','decision'],'proposed','S667; the program-requirements-harvest lane NEXT (4)',null,null,'SkyPlover (S667)',date '2026-11-16'),
('d-plain-words-one-rule-s667','decision','Plain words: one term list for the Commons and the decision sheets','S667, #3403 (0b12933c) and samueltlee/CPLBrain#806: kb/plain_words.py holds TERMS and offenses() once; tests/plain_words_for_sam_test.py imports it and fails a second copy; the vault''s sheet builder reads it and refuses a sheet from 201 on whose card uses a listed term undefined. Sheet 200 and earlier are named, never rebuilt.',array['governance-team-enablement','decision-sheets','decision'],'proposed','S667; #3403, CPLBrain#806',null,null,'SkyPlover (S667)',date '2026-11-16'),
('p-tab-listeners-share-one-registry-s667','pitfall','Two tabs that toggle one shared widget must ask one registry','S667, #3402: library.js set the Sierra chip off on every tab but its own, so once CPL Pathways also showed it, whichever cpl-tab-activated listener ran last won. Both now ask window.CPL_SIERRA_TABS[current tab], so the order does not matter; tests/cpl_pathways_side_panels.test.js fails the old rule.',array['cpl-pathways','library','pitfall'],'proposed','S667; #3402',null,null,'SkyPlover (S667)',date '2026-11-16')
on conflict (slug) do nothing;

